changeSet.sql:
-- Wipe and reseed character_skill_slots / character_skills / skills DELETE FROM character_skill_slots; DELETE FROM character_skills; DELETE FROM skills;
-- Reset sequence so id=1..10 are deterministic SELECT setval(pg_get_serial_sequence('skills','id'), 1, false);
-- Starter spells (id 1-5) INSERT INTO skills (name, skill_type, description, mana_cost, effect_json, icon_url) VALUES ('Fireball', 'spell', 'A blazing sphere of flame.', 10, '{"element":"fire","damage":25,"projectileScale":1.0,"color":[1.0,0.4,0.1]}', null), ('Ice Shard', 'spell', 'A razor-sharp shard of frost.', 8, '{"element":"ice","damage":20,"projectileScale":0.8,"color":[0.5,0.85,1.0]}', null), ('Thunder Bolt', 'spell', 'A crackling bolt of electricity.', 12, '{"element":"lightning","damage":28,"projectileScale":0.9,"color":[0.95,0.95,0.4]}', null), ('Stone Spike', 'spell', 'Conjures a jagged stone projectile.', 11, '{"element":"earth","damage":24,"projectileScale":1.1,"color":[0.55,0.4,0.25]}',null), ('Holy Light', 'spell', 'A radiant beam that heals or smites.', 14, '{"element":"light","damage":18,"heal":20,"projectileScale":1.2,"color":[1.0,0.95,0.7]}', null);
-- Advanced quest-locked spells (id 6-10) INSERT INTO skills (name, skill_type, description, mana_cost, effect_json, icon_url) VALUES ('Inferno Lance', 'spell', 'A piercing lance of roaring inferno.', 22, '{"element":"fire","damage":55,"projectileScale":1.6,"color":[1.0,0.2,0.05]}',null), ('Glacial Storm', 'spell', 'A spiraling tempest of ice.', 20, '{"element":"ice","damage":48,"projectileScale":1.5,"slow":true,"color":[0.6,0.95,1.0]}', null), ('Chain Lightning', 'spell', 'Forks of arcane lightning that chain.', 25, '{"element":"lightning","damage":62,"projectileScale":1.4,"chain":3,"color":[1.0,1.0,0.5]}', null), ('Earthquake', 'spell', 'Splits the ground in a shockwave.', 28, '{"element":"earth","damage":58,"projectileScale":1.8,"color":[0.45,0.3,0.2]}', null), ('Solar Flare', 'spell', 'A blinding flare of pure sunlight.', 30, '{"element":"light","damage":70,"heal":40,"projectileScale":2.0,"color":[1.0,0.9,0.4]}', null);
-- All five starter spells learned + slotted for character 1 INSERT INTO character_skills (character_id, skill_id) VALUES (1,1),(1,2),(1,3),(1,4),(1,5); INSERT INTO character_skill_slots (character_id, slot_number, skill_id) VALUES (1,1,1),(1,2,2),(1,3,3),(1,4,4),(1,5,5);
